import { getOptionalSession } from "@/server/session";
import { buildTrialBalanceTemplate, XLSX_TYPE } from "@/server/tb-template";
import { TEMPLATE_FILE_NAME } from "@/domain/tb-template";

export const dynamic = "force-dynamic";

/**
 * The LedgerFile trial balance template, generated by the app. It holds no client data, but like the rest of the product it is for signed-in users only:
 * a signed-out request is simply not found (not a redirect, which a download link cannot follow). Never cached.
 */
export async function GET() {
  const session = await getOptionalSession();
  if (!session) return new Response("Not found", { status: 404, headers: { "Cache-Control": "no-store" } });
  const file = await buildTrialBalanceTemplate();
  return new Response(new Uint8Array(file), {
    headers: { "Content-Type": XLSX_TYPE, "Content-Disposition": `attachment; filename="${TEMPLATE_FILE_NAME}"`, "Cache-Control": "no-store", "X-Content-Type-Options": "nosniff" },
  });
}
